const RecordUI=(()=>{const TYPES=['Contract','Change Order','Customer Invoice','Customer Payment','Subcontractor Bill','Supplier Bill','Insurance Record','Other'];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(+n||0);function form(jobId,r={}){return '<form id="recordForm" class="recordForm"><input type="hidden" name="id" value="'+esc(r.id||'')+'"><label>Record type<select name="type">'+TYPES.map(t=>'<option '+(r.type===t?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>Amount<input name="amount" inputmode="decimal" type="number" min="0" step=".01" value="'+esc(r.amount||'')+'"></label><label>Date<input name="date" type="date" value="'+esc(r.date||'')+'"></label><label>Party / company<input name="party" value="'+esc(r.party||'')+'" placeholder="Customer, subcontractor, supplier"></label><label>Status<select name="state"><option value="open">Open</option><option value="signed" '+(r.state==='signed'?'selected':'')+'>Signed / approved</option><option value="paid" '+(r.state==='paid'?'selected':'')+'>Paid</option></select></label><label>Notes<input name="notes" value="'+esc(r.notes||'')+'" placeholder="Description or reference"></label><div class="actions"><button class="btn primary">Save record</button><button type="button" id="cancelRecord" class="btn">Cancel</button></div></form>'}async function showForm(jobId,r){let host=document.getElementById('recordEditor');host.innerHTML=form(jobId,r);host.classList.remove('hidden');document.getElementById('cancelRecord').onclick=()=>host.classList.add('hidden');document.getElementById('recordForm').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));await JobDB.putRecord({id:d.id||undefined,jobId,type:d.type,amount:Math.max(0,Number(d.amount)||0),date:d.date,party:d.party.trim(),state:d.state,notes:d.notes.trim()});host.classList.add('hidden');window.dispatchEvent(new CustomEvent('job-records-changed',{detail:{jobId}}))}}async function list(jobId,types){let rs=await JobDB.records(jobId);if(types)rs=rs.filter(r=>types.includes(r.type));return rs.sort((a,b)=>(b.date||'').localeCompare(a.date||''))}function rows(rs){return rs.length?rs.map(r=>'<div class="recordRow"><div><b>'+esc(r.type)+'</b> · '+money(r.amount)+(r.party?' · '+esc(r.party):'')+'<br><span class="muted">'+esc(r.date||'No date')+' · '+esc(r.state||'open')+(r.notes?' · '+esc(r.notes):'')+'</span></div><div class="actions"><button class="btn" data-edit-record="'+r.id+'">Edit</button><button class="btn danger" data-delete-record="'+r.id+'">Remove</button></div></div>').join(''):'<p class="muted">No records yet.</p>'}async function bind(jobId,rs){document.querySelectorAll('[data-edit-record]').forEach(b=>b.onclick=()=>showForm(jobId,rs.find(r=>r.id===b.dataset.editRecord)));document.querySelectorAll('[data-delete-record]').forEach(b=>b.onclick=async()=>{if(confirm('Remove this construction record?')){await JobDB.deleteRecord(b.dataset.deleteRecord);window.dispatchEvent(new CustomEvent('job-records-changed',{detail:{jobId}}))}})}return{showForm,list,rows,bind}})();